import copy
import itertools


def expand_device_profiles(profiles):
    if not isinstance(profiles, (list, tuple)):
        raise ValueError("profiles must be a sequence")
    all_names = set()
    prepared = []
    for profile in profiles:
        if not isinstance(profile, dict):
            raise ValueError("profiles must contain dictionaries")
        kind = profile.get("kind")
        if not isinstance(kind, str) or not kind:
            raise ValueError("kind must be a non-empty string")
        names = []
        option_lists = []
        for name, values in profile.items():
            if name == "kind":
                continue
            if not isinstance(name, str) or not name or not isinstance(values, list):
                raise ValueError("invalid option")
            names.append(name)
            option_lists.append(values)
            all_names.add(name)
        prepared.append((kind, names, option_lists))

    ordered_names = sorted(all_names)
    rows = []
    for kind, names, option_lists in prepared:
        if not option_lists:
            continue
        for combination in itertools.product(*option_lists):
            selected = dict(zip(names, combination))
            row = {"device_kind": kind}
            for name in ordered_names:
                row[name] = copy.deepcopy(selected[name]) if name in selected else None
            rows.append(row)
    return rows

